-- Seed datasets applied to this database (versioned, idempotent reference data).
IF OBJECT_ID(N'[secureplus].[SeedVersion]', N'U') IS NULL
CREATE TABLE [secureplus].[SeedVersion] (
    [Dataset] NVARCHAR(64) NOT NULL,
    [Version] NVARCHAR(50) NOT NULL,
    [ContentHash] NVARCHAR(64) NOT NULL,
    [RowsApplied] INT NOT NULL,
    [AppliedAtUtc] DATETIME2 NOT NULL,
    [AppliedBy] NVARCHAR(256) NOT NULL,
    [Summary] NVARCHAR(2000) NULL,
    CONSTRAINT [PK_SeedVersion] PRIMARY KEY CLUSTERED ([Dataset])
);
GO
-- Solution areas and experience areas.
IF OBJECT_ID(N'[secureplus].[ReferenceValue]', N'U') IS NULL
CREATE TABLE [secureplus].[ReferenceValue] (
    [Category] NVARCHAR(50) NOT NULL,
    [Code] NVARCHAR(64) NOT NULL,
    [Name] NVARCHAR(200) NOT NULL,
    [Description] NVARCHAR(1000) NULL,
    [SortOrder] INT NOT NULL,
    CONSTRAINT [PK_ReferenceValue] PRIMARY KEY CLUSTERED ([Category], [Code])
);
GO
-- Remediation content and implementation details of each catalog control (EaaS v3 has no columns for them).
IF OBJECT_ID(N'[secureplus].[ControlDetail]', N'U') IS NULL
CREATE TABLE [secureplus].[ControlDetail] (
    [ControlId] NVARCHAR(150) NOT NULL,
    [SeedVersion] NVARCHAR(50) NOT NULL,
    [SolutionArea] NVARCHAR(64) NULL,
    [ExperienceArea] NVARCHAR(64) NULL,
    [VariantOf] NVARCHAR(150) NULL,
    [VariantLabel] NVARCHAR(400) NULL,
    [ComplianceStandards] NVARCHAR(MAX) NULL,
    [EstimatedMinutes] INT NULL,
    [Difficulty] NVARCHAR(20) NULL,
    [Effort] NVARCHAR(20) NULL,
    [RiskLevel] NVARCHAR(20) NULL,
    [Benefits] NVARCHAR(1000) NULL,
    [ExperienceImpact] NVARCHAR(2000) NULL,
    [GraphRequest] NVARCHAR(MAX) NULL,
    [GraphCommand] NVARCHAR(MAX) NULL,
    [PowerShell] NVARCHAR(MAX) NULL,
    [JsonBody] NVARCHAR(MAX) NULL,
    [SettingPath] NVARCHAR(2000) NULL,
    [GpoPath] NVARCHAR(2000) NULL,
    [Registry] NVARCHAR(2000) NULL,
    [Generated] NVARCHAR(1000) NULL,
    [UpdatedAtUtc] DATETIME2 NOT NULL,
    CONSTRAINT [PK_ControlDetail] PRIMARY KEY CLUSTERED ([ControlId])
);
GO
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'IX_ControlDetail_SolutionArea' AND object_id = OBJECT_ID(N'[secureplus].[ControlDetail]'))
    CREATE NONCLUSTERED INDEX [IX_ControlDetail_SolutionArea] ON [secureplus].[ControlDetail] ([SolutionArea]);
GO
-- Old control IDs of merged duplicates; results stored with an alias resolve to ControlId.
IF OBJECT_ID(N'[secureplus].[ControlAlias]', N'U') IS NULL
CREATE TABLE [secureplus].[ControlAlias] (
    [Alias] NVARCHAR(150) NOT NULL,
    [ControlId] NVARCHAR(150) NOT NULL,
    [Reason] NVARCHAR(1000) NULL,
    CONSTRAINT [PK_ControlAlias] PRIMARY KEY CLUSTERED ([Alias])
);
GO
-- Run history of recurring assessment schedules.
IF OBJECT_ID(N'[secureplus].[ScheduleRun]', N'U') IS NULL
