-- Specifications: standard (unassigned) or tailored. Linked to spec.Specification when assigned to an engagement.
IF OBJECT_ID(N'[secureplus].[Specification]', N'U') IS NULL
CREATE TABLE [secureplus].[Specification] (
    [SpecificationKey] NVARCHAR(64) NOT NULL,
    [Name] NVARCHAR(200) NOT NULL,
    [Description] NVARCHAR(2000) NULL,
    [IsStandard] BIT NOT NULL,
    [IsSystem] BIT NOT NULL,
    [IsModified] BIT NOT NULL,
    [BasedOnKey] NVARCHAR(64) NULL,
    [StatusCode] NVARCHAR(20) NOT NULL,
    [SeedVersion] NVARCHAR(50) NULL,
    [CreatedBy] NVARCHAR(256) NOT NULL,
    [CreatedAtUtc] DATETIME2 NOT NULL,
    [ModifiedBy] NVARCHAR(256) NULL,
    [ModifiedAtUtc] DATETIME2 NULL,
    CONSTRAINT [PK_Specification] PRIMARY KEY CLUSTERED ([SpecificationKey])
);
GO
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_Specification_Name' AND object_id = OBJECT_ID(N'[secureplus].[Specification]'))
    CREATE UNIQUE NONCLUSTERED INDEX [UX_Specification_Name] ON [secureplus].[Specification] ([Name]);
GO
-- Members of a specification: Experience, Framework, ComplianceStandard, Requirement, PolicySet, Control or Policy.
