    [Impact] NVARCHAR(2000) NULL,
    [RollbackPlan] NVARCHAR(MAX) NULL,
    [RequestedBy] NVARCHAR(256) NOT NULL,
    [ApprovedBy] NVARCHAR(256) NULL,
    [Owner] NVARCHAR(256) NULL,
    [WindowStartUtc] DATETIME2 NULL,
    [WindowEndUtc] DATETIME2 NULL,
    [StatusCode] NVARCHAR(20) NOT NULL,
    [DecisionNote] NVARCHAR(2000) NULL,
    [CreatedAtUtc] DATETIME2 NOT NULL,
    [ModifiedAtUtc] DATETIME2 NOT NULL,
    [DecidedAtUtc] DATETIME2 NULL,
    [CompletedAtUtc] DATETIME2 NULL,
    CONSTRAINT [PK_ChangeRequest] PRIMARY KEY CLUSTERED ([ChangeRequestId])
);
GO
